create table public.buyers (id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id) on delete cascade,name text not null check(char_length(trim(name))>0),phone text,notes text,created_at timestamptz not null default now(),unique(farm_id,name));
create table public.sales (id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id) on delete cascade,crop_cycle_id uuid not null references public.crop_cycles(id) on delete cascade,buyer_id uuid references public.buyers(id) on delete set null,sale_date date not null default current_date,quantity numeric(14,3) not null check(quantity>0),unit text not null check(unit in ('kg','ton','maund','bag','unit')),rate_per_unit numeric(14,2) not null check(rate_per_unit>=0),total_amount numeric(14,2) generated always as (round(quantity*rate_per_unit,2)) stored,payment_status text not null default 'unpaid' check(payment_status in ('unpaid','partial','paid')),notes text,created_at timestamptz not null default now());
create index buyers_farm_id_idx on public.buyers(farm_id);create index sales_farm_id_idx on public.sales(farm_id);create index sales_crop_cycle_id_idx on public.sales(crop_cycle_id);create index sales_buyer_id_idx on public.sales(buyer_id);create index sales_date_idx on public.sales(sale_date);
alter table public.buyers enable row level security;alter table public.sales enable row level security;
create policy "owners manage buyers select" on public.buyers for select to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners manage buyers insert" on public.buyers for insert to authenticated with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners manage buyers update" on public.buyers for update to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners manage buyers delete" on public.buyers for delete to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners select sales" on public.sales for select to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
create policy "owners insert sales" on public.sales for insert to authenticated with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())) and exists(select 1 from public.crop_cycles c where c.id=crop_cycle_id and c.farm_id=farm_id) and (buyer_id is null or exists(select 1 from public.buyers b where b.id=buyer_id and b.farm_id=farm_id)));
create policy "owners update sales" on public.sales for update to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid()))) with check(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())) and exists(select 1 from public.crop_cycles c where c.id=crop_cycle_id and c.farm_id=farm_id) and (buyer_id is null or exists(select 1 from public.buyers b where b.id=buyer_id and b.farm_id=farm_id)));
create policy "owners delete sales" on public.sales for delete to authenticated using(exists(select 1 from public.farms f where f.id=farm_id and f.owner_id=(select auth.uid())));
grant select,insert,update,delete on public.buyers,public.sales to authenticated;